SC = []
def add(say, scene, at, src=None, dark=False, chapter=None, instruct=None, hold=None):
    d = {'say': say}
    if instruct: d['instruct'] = instruct
    if chapter: d['chapter'] = chapter
    if src: d['source'] = src
    if dark: d['theme'] = 'dark'
    if hold: d['hold'] = hold
    d['scene'] = scene; d['sync'] = {'at': [0] + at}; SC.append(d)
def Q(text, by): return {'kind': 'quote', 'text': text, 'by': by}
def BN(label, to, unit, color, sub, frm=0): return {'kind': 'bignum', 'label': label, 'from': frm, 'to': to, 'unit': unit, 'color': color, 'sub': sub}
def CH(k, t): return {'kind': 'chapter', 'kicker': k, 'title': t}
def DOC(tag, meta, title, lines): return {'kind': 'doc', 'tag': tag, 'meta': meta, 'title': title, 'lines': lines}
def BARS(title, sub, items, unit=None, v=False):
    d = {'kind': 'bars', 'title': title, 'sub': sub, 'items': [{'label': a, 'value': b, 'color': c} for a, b, c in items]}
    if unit: d['unit'] = unit
    if v: d['dir'] = 'v'
    return d
def STACK(logo, label, cards): return {'kind': 'stack', 'logo': logo, 'label': label, 'cards': [{'meta': a, 'text': b} for a, b in cards]}
def FLIP(label, a, b): return {'kind': 'flip', 'label': label, 'from': a, 'to': b}
